export interface ConnectorConfig {
  /** Pusher Channels App ID */
  pusherAppId: string
  /** Pusher Channels Key (public key) */
  pusherKey: string
  /** Pusher Channels Secret (private key) for signing auth_signature */
  pusherSecret: string
  /** Pusher Channels cluster host, e.g. 'hosted.pusherapp.com' or 'api-mt1.pusher.com' */
  pusherCluster?: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface ZendeskTicketPayload {
  ticket: {
    id: number
    status: string
    subject: string
    latest_comment?: string
    updater: {
      name: string
    }
    timestamp: string
  }
}

export interface PusherTriggerResult {
  channel: string
  event: string
  status: number
}

function validatePayload(payload: unknown): asserts payload is ZendeskTicketPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (!p.ticket || typeof p.ticket !== 'object') {
    throw new Error('Missing required field: ticket')
  }
  const ticket = p.ticket as Record<string, unknown>
  if (typeof ticket.id !== 'number') {
    throw new Error('Missing required field: ticket.id (number)')
  }
  if (typeof ticket.status !== 'string') {
    throw new Error('Missing required field: ticket.status (string)')
  }
  if (typeof ticket.subject !== 'string') {
    throw new Error('Missing required field: ticket.subject (string)')
  }
  if (!ticket.updater || typeof ticket.updater !== 'object' || typeof (ticket.updater as Record<string, unknown>).name !== 'string') {
    throw new Error('Missing required field: ticket.updater.name (string)')
  }
  if (typeof ticket.timestamp !== 'string') {
    throw new Error('Missing required field: ticket.timestamp (string)')
  }
}

async function hmacSha256(secret: string, message: string): Promise<string> {
  const encoder = new TextEncoder()
  const key = await crypto.subtle.importKey(
    'raw',
    encoder.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  )
  const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(message))
  return Array.from(new Uint8Array(signature))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('')
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<PusherTriggerResult> {
  validatePayload(payload)
  const { ticket } = payload as ZendeskTicketPayload

  const appId = config.pusherAppId
  const key = config.pusherKey
  const secret = config.pusherSecret
  const cluster = config.pusherCluster ?? 'hosted.pusherapp.com'
  const fetchImpl = config.fetch ?? fetch

  const channelName = `presence-ticket-${ticket.id}`
  const eventName = 'ticket.updated'
  const eventData = {
    subject: ticket.subject,
    latest_comment: ticket.latest_comment ?? '',
    updater_name: ticket.updater.name,
    timestamp: ticket.timestamp
  }

  const authTimestamp = Math.floor(Date.now() / 1000).toString()
  const authVersion = '1.0'
  const path = `/apps/${appId}/channels/${channelName}/events`
  const queryParams = new URLSearchParams({
    auth_key: key,
    auth_timestamp: authTimestamp,
    auth_version: authVersion
  })
  const stringToSign = `POST\n${path}\n${queryParams.toString()}`
  const authSignature = await hmacSha256(secret, stringToSign)
  queryParams.set('auth_signature', authSignature)

  const url = `https://${cluster}${path}?${queryParams.toString()}`
  const body = JSON.stringify({ name: eventName, data: eventData })

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body
  })

  if (!response.ok) {
    throw new Error(`Pusher Channels request failed: ${response.status} ${response.statusText} for ${url}`)
  }

  return {
    channel: channelName,
    event: eventName,
    status: response.status
  }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, ZendeskTicketPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      pusherAppId: 'test-app-id',
      pusherKey: 'test-key',
      pusherSecret: 'test-secret',
      pusherCluster: 'hosted.pusherapp.com',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ZendeskTicketPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.channel).toBe('presence-ticket-12345')
    expect(result.event).toBe('ticket.updated')
    expect(result.status).toBe(200)
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    baseConfig = {
      pusherAppId: 'app-123',
      pusherKey: 'key-456',
      pusherSecret: 'secret-789',
      pusherCluster: 'hosted.pusherapp.com'
    }
  })

  it('sends correct request with all fields mapped', async () => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toContain('/apps/app-123/channels/presence-ticket-12345/events')
      expect(req.url).toContain('auth_key=key-456')
      expect(req.url).toContain('auth_timestamp=')
      expect(req.url).toContain('auth_version=1.0')
      expect(req.url).toContain('auth_signature=')
      const json = req.json as Record<string, unknown>
      expect(json.name).toBe('ticket.updated')
      expect(json.data).toEqual({
        subject: 'Sample ticket subject',
        latest_comment: 'This is a sample comment',
        updater_name: 'John Doe',
        timestamp: '2026-03-15T10:30:00Z'
      })
      return jsonResponse({}, 200)
    })
    calls = recordedCalls

    const payload: ZendeskTicketPayload = {
      ticket: {
        id: 12345,
        status: 'open',
        subject: 'Sample ticket subject',
        latest_comment: 'This is a sample comment',
        updater: { name: 'John Doe' },
        timestamp: '2026-03-15T10:30:00Z'
      }
    }

    const result = await handle(payload, { ...baseConfig, fetch })
    expect(result.channel).toBe('presence-ticket-12345')
    expect(result.event).toBe('ticket.updated')
    expect(result.status).toBe(200)
    expect(calls.length).toBe(1)
  })

  it('includes auth mechanism with HMAC-SHA256 signature', async () => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      const url = new URL(req.url)
      const authSignature = url.searchParams.get('auth_signature')
      expect(authSignature).toBeDefined()
      expect(authSignature!.length).toBe(64) // 32 bytes hex = 64 chars
      return jsonResponse({}, 200)
    })
    calls = recordedCalls

    const payload: ZendeskTicketPayload = {
      ticket: {
        id: 999,
        status: 'pending',
        subject: 'Test',
        updater: { name: 'Agent' },
        timestamp: '2026-01-01T00:00:00Z'
      }
    }

    await handle(payload, { ...baseConfig, fetch })
    expect(calls.length).toBe(1)
  })

  it('maps ticket fields to event data correctly', async () => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      const json = req.json as Record<string, unknown>
      const data = json.data as Record<string, unknown>
      expect(data.subject).toBe('Custom subject')
      expect(data.latest_comment).toBe('Custom comment')
      expect(data.updater_name).toBe('Jane Smith')
      expect(data.timestamp).toBe('2026-06-15T14:22:00Z')
      return jsonResponse({}, 200)
    })
    calls = recordedCalls

    const payload: ZendeskTicketPayload = {
      ticket: {
        id: 555,
        status: 'solved',
        subject: 'Custom subject',
        latest_comment: 'Custom comment',
        updater: { name: 'Jane Smith' },
        timestamp: '2026-06-15T14:22:00Z'
      }
    }

    await handle(payload, { ...baseConfig, fetch })
    expect(calls.length).toBe(1)
  })

  it('throws on missing required field ticket.id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      ticket: {
        status: 'open',
        subject: 'Test',
        updater: { name: 'Agent' },
        timestamp: '2026-01-01T00:00:00Z'
      }
    }

    await expect(handle(payload as unknown as ZendeskTicketPayload, { ...baseConfig, fetch }))
      .rejects.toThrow('Missing required field: ticket.id (number)')
  })

  it('throws on missing required field ticket.updater.name', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = {
      ticket: {
        id: 1,
        status: 'open',
        subject: 'Test',
        updater: {},
        timestamp: '2026-01-01T00:00:00Z'
      }
    }

    await expect(handle(payload as unknown as ZendeskTicketPayload, { ...baseConfig, fetch }))
      .rejects.toThrow('Missing required field: ticket.updater.name (string)')
  })

  it('throws on non-2xx response from Pusher', async () => {
    const { fetch, calls: recordedCalls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    calls = recordedCalls

    const payload: ZendeskTicketPayload = {
      ticket: {
        id: 1,
        status: 'open',
        subject: 'Test',
        updater: { name: 'Agent' },
        timestamp: '2026-01-01T00:00:00Z'
      }
    }

    await expect(handle(payload, { ...baseConfig, fetch }))
      .rejects.toThrow('Pusher Channels request failed: 401 Unauthorized')
    expect(calls.length).toBe(1)
  })

  it('handles optional latest_comment being absent', async () => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      const json = req.json as Record<string, unknown>
      const data = json.data as Record<string, unknown>
      expect(data.latest_comment).toBe('')
      return jsonResponse({}, 200)
    })
    calls = recordedCalls

    const payload: ZendeskTicketPayload = {
      ticket: {
        id: 777,
        status: 'open',
        subject: 'No comment',
        updater: { name: 'Bot' },
        timestamp: '2026-07-01T12:00:00Z'
      }
    }

    await handle(payload, { ...baseConfig, fetch })
    expect(calls.length).toBe(1)
  })

  it('uses custom cluster host when provided', async () => {
    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      expect(req.url).toContain('api-custom.pusher.com')
      return jsonResponse({}, 200)
    })
    calls = recordedCalls

    const payload: ZendeskTicketPayload = {
      ticket: {
        id: 111,
        status: 'open',
        subject: 'Test',
        updater: { name: 'Agent' },
        timestamp: '2026-01-01T00:00:00Z'
      }
    }

    await handle(payload, { ...baseConfig, pusherCluster: 'api-custom.pusher.com', fetch })
    expect(calls.length).toBe(1)
  })
})

